def fill_details(apps, schema_editor):
    Machine = apps.get_model("messen", "UsedMachine")
    for position, (serial, title, year, month, hours, engine, power, shafts, equipment, condition, weight, updated) in enumerate(DATA):
        obj, created = Machine.objects.get_or_create(serial_number=serial, defaults={"title": title, "build_year": year, "build_month": month, "position": position, "published": False})
        # Fill only empty fields so employees’ changes are not overwritten.
        changed = []
        for field, value in {"operating_hours":hours,"engine":engine,"power":power,"shafts":shafts,"equipment":equipment,"condition":condition,"weight":weight,"description":"Technische Angaben laut bisherigem HAMMEL-Katalog (Stand: "+updated+"). Verfügbarkeit und Ausstattung bitte vor Veröffentlichung prüfen."}.items():
            if value and not getattr(obj, field):
                setattr(obj, field, value)
                changed.append(field)
        if changed: obj.save(update_fields=changed)

class Migration(migrations.Migration):
    dependencies = [("messen", "0008_usedmachines")]
